class Spieler:
    def __init__(self, name):
        self.name = name
        self.punkte = 0

def gewinnt(s, wert):
    s.punkte = s.punkte + wert

def zuruecksetzen(s):
    s = Spieler(s.name)

anna = Spieler("Anna")
gewinnt(anna, 7)
zuruecksetzen(anna)
print(anna.name, anna.punkte)

